#!/usr/bin/env node
// SPDX-License-Identifier: GPL-3.0-or-later
// Writes packages/dungeonmaker-js/src/version.ts from the package version. Run by `build`
// and by the npm `version` lifecycle; a test compares the result with package.json.
import { readFileSync, writeFileSync } from 'node:fs';

const pkgUrl = new URL('../packages/dungeonmaker-js/', import.meta.url);
const { version } = JSON.parse(readFileSync(new URL('package.json', pkgUrl), 'utf8'));
writeFileSync(
  new URL('src/version.ts', pkgUrl),
  `// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by scripts/write-version.mjs from package.json. Do not edit by hand.
export const VERSION = '${version}';
`,
);
